-- ===== Catalog census =====
select is(
  (select count(*)::int from pg_proc p where p.pronamespace = 'public'::regnamespace and has_function_privilege('anon', p.oid, 'EXECUTE')),
  0, 'census: anon (incl. PUBLIC) can EXECUTE no function in schema public');

select set_eq(
  $q$select p.proname::text from pg_proc p where p.pronamespace = 'public'::regnamespace and has_function_privilege('authenticated', p.oid, 'EXECUTE')$q$,
  $q$values ('is_active_member'), ('job_status_summary'), ('usage_daily_summary'), ('knowledge_gaps')$q$,
  'census: authenticated can EXECUTE exactly is_active_member + the three safe RPCs');

select is(
  (select count(*)::int from pg_proc p, lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
    where p.pronamespace = 'public'::regnamespace and a.grantee = 0 and a.privilege_type = 'EXECUTE'),
  0, 'census: no function in schema public is executable by PUBLIC');

select set_eq(
  $q$select p.proname::text from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prosecdef$q$,
  $q$values ('is_active_member'), ('job_status_summary'), ('usage_daily_summary'), ('knowledge_gaps')$q$,
  'census: SECURITY DEFINER functions are exactly the four membership-checked ones');

select is(
  (select count(*)::int from pg_proc p where p.pronamespace = 'public'::regnamespace
     and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%')),
  0, 'census: every function in schema public pins search_path');

select is(
  (select count(*)::int from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prosecdef
     and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) c where c in ('search_path=""', 'search_path=')) ),
  0, 'census: every SECURITY DEFINER function uses an empty search_path');

select is(
  (select count(*)::int from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p') and not c.relrowsecurity),
  0, 'census: RLS is enabled on every table in schema public');

select is(
  (select count(*)::int from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('v', 'm')),
  0, 'census: no views/materialized views in schema public (nothing to wrap as security_invoker)');

select set_eq(
  $q$select distinct table_name::text from information_schema.role_table_grants where grantee = 'anon' and table_schema = 'public'$q$,
  $q$values ('public_bot_config')$q$,
  'census: anon has table privileges on public_bot_config ONLY');

select set_eq(
  $q$select privilege_type::text from information_schema.role_table_grants where grantee = 'anon' and table_schema = 'public'$q$,
  $q$values ('SELECT')$q$,
  'census: anon privilege on public_bot_config is SELECT only');

select is(
  (select count(*)::int from information_schema.role_table_grants
    where grantee = 'authenticated' and table_schema = 'public' and privilege_type <> 'SELECT'),
  0, 'census: authenticated has no INSERT/UPDATE/DELETE/TRUNCATE/REFERENCES/TRIGGER on any public table');

select set_eq(
  $q$select distinct table_name::text from information_schema.role_table_grants where grantee = 'authenticated' and table_schema = 'public'$q$,
  $q$values ('public_bot_config'), ('documents'), ('document_versions'), ('conversations'), ('messages'), ('message_sources'), ('conversation_analysis'), ('data_entries'), ('audit_logs')$q$,
  'census: authenticated SELECT grants are exactly the matrix-permitted relations');

select is(
  (select count(*)::int from information_schema.role_usage_grants where grantee in ('anon', 'authenticated') and object_schema = 'public'),
  0, 'census: anon/authenticated hold no sequence/other usage grants in public');

select is(
  (select count(*)::int from pg_default_acl d, lateral aclexplode(d.defaclacl) a
    where d.defaclnamespace = 'public'::regnamespace and d.defaclrole = (select oid from pg_roles where rolname = 'postgres') and a.grantee in (select oid from pg_roles where rolname in ('anon', 'authenticated'))),
  0, 'census: no default privileges for anon/authenticated remain for objects created by postgres (migration owner) in schema public');

-- Foreign-key index coverage: every FK has an index whose leading columns are the FK columns.
select is(
  (select count(*)::int
     from pg_constraint c
    where c.contype = 'f' and c.connamespace = 'public'::regnamespace
      and not exists (
        select 1 from pg_index i
         where i.indrelid = c.conrelid
           and i.indisvalid
           and (select array_agg(k order by k) from unnest((i.indkey::int2[])[0:cardinality(c.conkey) - 1]) k)
               = (select array_agg(k order by k) from unnest(c.conkey) k)
      )),
  0, 'census: every foreign key is covered by an index');

select * from finish();
rollback;
